css:
.codefin-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
    min-height: 100vh;
    font-family: 'Fira Code', 'Consolas', 'Monaco', monospace;
    color: #e0e0e0;
}

.codefin-sim-header {
    background: linear-gradient(135deg, #00b4d8 0%, #0077b6 100%);
    color: white;
    padding: 30px;
    border-radius: 16px;
    margin-bottom: 30px;
    box-shadow: 0 8px 32px rgba(0, 180, 216, 0.3);
    text-align: center;
    position: relative;
    overflow: hidden;
}

.codefin-sim-header::before {
    content: '>>> ';
    position: absolute;
    top: 10px;
    left: 15px;
    font-size: 0.8rem;
    opacity: 0.5;
    font-family: 'Fira Code', monospace;
}

.codefin-sim-header h1 {
    font-size: 1.8rem;
    margin-bottom: 8px;
    font-weight: 700;
}

.codefin-sim-header p {
    font-size: 1rem;
    opacity: 0.9;
    margin: 0;
}

.codefin-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 25px;
    color: #90caf9;
    font-weight: 600;
}

.codefin-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 30px;
}

.codefin-sim-status-card {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 20px 16px;
    text-align: center;
    backdrop-filter: blur(10px);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.codefin-sim-status-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.codefin-sim-card-score {
    border-color: rgba(0, 180, 216, 0.4);
}

.codefin-sim-card-grade {
    border-color: rgba(255, 183, 77, 0.4);
}

.codefin-sim-card-best {
    border-color: rgba(102, 187, 106, 0.4);
}

.codefin-sim-card-avg {
    border-color: rgba(186, 104, 200, 0.4);
}

.codefin-sim-label {
    color: #90a4ae;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 8px;
}

.codefin-sim-value {
    font-size: 1.8rem;
    font-weight: 700;
    color: #e0e0e0;
}

.codefin-sim-card-score .codefin-sim-value {
    color: #00b4d8;
}

.codefin-sim-card-grade .codefin-sim-value {
    color: #ffb74d;
}

.codefin-sim-card-best .codefin-sim-value {
    color: #66bb6a;
}

.codefin-sim-card-avg .codefin-sim-value {
    color: #ba68c8;
}

.codefin-sim-briefing {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(0, 180, 216, 0.3);
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 30px;
    position: relative;
}

.codefin-sim-briefing-badge {
    display: inline-block;
    background: rgba(0, 180, 216, 0.2);
    color: #00b4d8;
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 12px;
}

.codefin-sim-briefing h3 {
    color: #ffffff;
    font-size: 1.3rem;
    margin-bottom: 12px;
}

.codefin-sim-briefing-text {
    color: #b0bec5;
    line-height: 1.7;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    font-size: 0.95rem;
}

.codefin-sim-controls {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 30px;
}

.codefin-sim-controls h3 {
    color: #90caf9;
    font-size: 1.1rem;
    margin-bottom: 20px;
}

.codefin-sim-input-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}

.codefin-sim-input-group label {
    display: block;
    color: #b0bec5;
    font-size: 0.85rem;
    margin-bottom: 6px;
    font-weight: 600;
}

.codefin-sim-input-group .form-control {
    background: rgba(0, 0, 0, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: #e0e0e0;
    border-radius: 8px;
    padding: 10px 14px;
    font-family: 'Fira Code', monospace;
    font-size: 1rem;
}

.codefin-sim-input-group .form-control:focus {
    border-color: #00b4d8;
    box-shadow: 0 0 0 3px rgba(0, 180, 216, 0.2);
    outline: none;
    background: rgba(0, 0, 0, 0.4);
}

.codefin-sim-hint {
    display: block;
    color: #78909c;
    font-size: 0.75rem;
    margin-top: 4px;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.codefin-sim-submit {
    display: block;
    width: 100%;
    padding: 14px;
    font-size: 1.1rem;
    font-weight: 700;
    border-radius: 10px;
    background: linear-gradient(135deg, #00b4d8 0%, #0077b6 100%);
    border: none;
    margin-bottom: 10px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.codefin-sim-submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0, 180, 216, 0.4);
}

.codefin-sim-history {
    margin-bottom: 30px;
}

.codefin-sim-container .table {
    color: #e0e0e0;
    background: rgba(255, 255, 255, 0.03);
    border-radius: 10px;
    overflow: hidden;
}

.codefin-sim-container .table thead th {
    background: rgba(0, 180, 216, 0.15);
    border-color: rgba(255, 255, 255, 0.1);
    color: #90caf9;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.codefin-sim-container .table td {
    border-color: rgba(255, 255, 255, 0.05);
    font-size: 0.9rem;
}

.codefin-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255, 255, 255, 0.02);
}

.codefin-sim-chart {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 20px;
    min-height: 300px;
}

@media (max-width: 768px) {
    .codefin-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .codefin-sim-input-row {
        grid-template-columns: 1fr;
    }
    .codefin-sim-header h1 {
        font-size: 1.4rem;
    }
}
/* --- Completion debrief (v1.1.0) --- */
.codefin-cm {
    background: #ffffff;
    color: #1a1a2e;
    border-radius: 16px;
    padding: 28px;
    max-width: 480px;
    margin: 0 auto;
    text-align: center;
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.codefin-cm-title {
    font-size: 1.4rem;
    font-weight: 700;
    color: #0077b6;
    margin-bottom: 12px;
}

.codefin-cm-score {
    font-size: 3rem;
    font-weight: 800;
    color: #00b4d8;
    line-height: 1;
    font-family: 'Fira Code', 'Consolas', monospace;
}

.codefin-cm-score-max {
    font-size: 1.1rem;
    color: #90a4ae;
    font-weight: 600;
}

.codefin-cm-grade {
    display: inline-block;
    margin: 14px 0 18px;
    padding: 6px 16px;
    border-radius: 20px;
    background: rgba(0, 180, 216, 0.12);
    font-size: 0.95rem;
    color: #0f0c29;
}

.codefin-cm-grade-A { background: rgba(102, 187, 106, 0.18); }
.codefin-cm-grade-B { background: rgba(0, 180, 216, 0.15); }
.codefin-cm-grade-C { background: rgba(255, 183, 77, 0.18); }
.codefin-cm-grade-D { background: rgba(255, 112, 67, 0.18); }
.codefin-cm-grade-F { background: rgba(239, 83, 80, 0.18); }

.codefin-cm-stats {
    display: flex;
    justify-content: center;
    gap: 28px;
    margin-bottom: 18px;
}

.codefin-cm-stat {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.codefin-cm-stat span {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #78909c;
}

.codefin-cm-stat b {
    font-size: 1.1rem;
    color: #1a1a2e;
    font-family: 'Fira Code', 'Consolas', monospace;
}

.codefin-cm-insights {
    text-align: left;
    background: #f4f7fb;
    border-radius: 10px;
    padding: 14px 18px;
}

.codefin-cm-insights-h {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #0077b6;
    font-weight: 700;
    margin-bottom: 6px;
}

.codefin-cm-insights ul {
    margin: 0;
    padding-left: 18px;
}

.codefin-cm-insights li {
    font-size: 0.9rem;
    line-height: 1.5;
    color: #37474f;
    margin-bottom: 4px;
}

