                    description: 'You are fitting a <b>GARCH(1,1)</b> model to daily return data to forecast volatility. The model is: <b>sigma_t^2 = omega + alpha * r_(t-1)^2 + beta * sigma_(t-1)^2</b>.<br><br>Choose the <b>alpha</b> (reaction to new shocks) and <b>beta</b> (persistence of past variance) parameters. Note: alpha + beta must be less than 1 for stationarity. The system evaluates model fit quality.<br><br>Your goal: find the parameter combination with the best fit to the data.',
                    param1Label: 'Alpha (shock reaction)',
                    param2Label: 'Beta (persistence)',
                    param1Hint: 'Range: 0.01 to 0.30',
                    param2Hint: 'Range: 0.50 to 0.98',
                    param1Min: 0.01, param1Max: 0.30, param1Step: 0.01, param1Default: 0.08,
                    param2Min: 0.50, param2Max: 0.98, param2Step: 0.01, param2Default: 0.85
                },
                {
                    badge: 'Task 6 / 6',
                    title: 'Monte Carlo Value-at-Risk',
                    description: 'You are building a <b>Monte Carlo VaR</b> model for a $1,000,000 equity portfolio. The model simulates thousands of return paths using geometric Brownian motion with annual drift 8% and annual volatility 22%.<br><br>Choose the <b>confidence level</b> and the <b>time horizon</b>. Higher confidence means a more extreme tail loss estimate; longer horizons compound uncertainty.<br><br>Your goal: select parameters that produce a VaR estimate closest to the regulatory benchmark.',
                    param1Label: 'Confidence Level (%)',
                    param2Label: 'Time Horizon (days)',
                    param1Hint: 'Range: 90 to 99',
                    param2Hint: 'Range: 1 to 30',
                    param1Min: 90, param1Max: 99, param1Step: 0.5, param1Default: 95,
                    param2Min: 1, param2Max: 30, param2Step: 1, param2Default: 10
                }
            ];
        }

        // Localized text helper: prefer framework i18n, fall back to English literal.
        _t(key, fallback) {
            var val = key;
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                val = window.mySimulation.t(key);
            }
            if (val === key || val === undefined || val === null) {
                return (fallback !== undefined) ? fallback : key;
            }
            return val;
        }

        // History detail line: translated template with {name} placeholders filled at render time
        _detailText(key, vals) {
            var out = this._t(key, '');
            var v = vals || {};
            for (var k in v) { if (Object.prototype.hasOwnProperty.call(v, k)) { out = String(out).split('{' + k + '}').join(String(v[k])); } }
            return out;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    bestScore: 0,
                    scoreHistory: [],
                    taskNames: [],
                    completedTasks: 0,
                    performance: { overallScore: 0, score: 0, grade: 'F', performanceTier: 'novice' },
                    performanceTier: 'novice'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    param1: this.ROUNDS[0].param1Default,
                    param2: this.ROUNDS[0].param2Default
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // NOTE: do NOT call _updateBriefing here. It resets the inputs to the
            // round defaults, which previously clobbered the learner's typed values
            // before they were read (every submission scored the defaults).
            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var p1 = document.getElementById('param1Input');
            var p2 = document.getElementById('param2Input');
            // Inputs start blank: a blank parameter is refused and never scored
            if ((p1 && String(p1.value).trim() === '') || (p2 && String(p2.value).trim() === '')) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('param_blank_warning'), 'warning'
                );
                return false;
            }
            if (p1) decisions.param1 = parseFloat(p1.value);
            if (p2) decisions.param2 = parseFloat(p2.value);

            if (isNaN(decisions.param1) || decisions.param1 < round.param1Min || decisions.param1 > round.param1Max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('param1_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.param2) || decisions.param2 < round.param2Min || decisions.param2 > round.param2Max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('param2_warning'), 'warning'
                );
                return false;
            }

            if (idx === 2 && decisions.param1 >= decisions.param2) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('ma_order_warning'), 'warning'
                );
                return false;
            }
            if (idx === 4 && (decisions.param1 + decisions.param2) >= 1.0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('garch_stationarity_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var d = state.decisions;
            var taskScore = 0;
            var detail = '';
            var detailKey = '';
            var detailVals = {};

            if (idx === 0) {
                var w = d.param1 / 100;
                var rf = d.param2 / 100;
                var rStock = 0.12;
                var rBond = 0.04;
                var sStock = 0.20;
                var sBond = 0.05;
                var corr = 0.20;
                var portReturn = w * rStock + (1 - w) * rBond;
                var portVol = Math.sqrt(
                    Math.pow(w * sStock, 2) +
                    Math.pow((1 - w) * sBond, 2) +
                    2 * w * (1 - w) * sStock * sBond * corr
                );
                var sharpe = portVol > 0 ? (portReturn - rf) / portVol : 0;
                taskScore = Math.min(100, Math.max(0, Math.round(sharpe * 60)));
                detailKey = 'detail_t1'; detailVals = { ret: (portReturn * 100).toFixed(2), vol: (portVol * 100).toFixed(2), sharpe: sharpe.toFixed(3) };
            }

            if (idx === 1) {
                var lookback = d.param1;
                var smooth = d.param2;
                var trueCorr = 0.35;
                var nObs = lookback / Math.max(1, smooth * 0.5);
                var noise = 0.4 / Math.sqrt(Math.max(nObs, 1));
                var regimePenalty = lookback > 300 ? (lookback - 300) * 0.0004 : 0;
                var overSmooth = smooth > 12 ? (smooth - 12) * 0.015 : 0;
                var estimatedCorr = trueCorr + noise - regimePenalty + overSmooth;
                var error = Math.abs(estimatedCorr - trueCorr);
                taskScore = Math.min(100, Math.max(0, Math.round(100 - error * 300)));
                detailKey = 'detail_t2'; detailVals = { est: estimatedCorr.toFixed(3), truth: trueCorr.toFixed(3), err: error.toFixed(3) };
            }

            if (idx === 2) {
                var shortMA = d.param1;
                var longMA = d.param2;
                var signalFreq = 252 / (longMA - shortMA);
                var txCost = signalFreq * 0.001;
                var trendCapture = 1 - Math.abs(shortMA - 20) * 0.005 - Math.abs(longMA - 120) * 0.002;
                var grossReturn = Math.max(0, trendCapture * 0.15);
                var netReturn = grossReturn - txCost;
                var stratVol = 0.12 + (signalFreq * 0.005);
                var riskAdjReturn = stratVol > 0 ? netReturn / stratVol : 0;
                taskScore = Math.min(100, Math.max(0, Math.round(riskAdjReturn * 100)));
                detailKey = 'detail_t3'; detailVals = { gross: (grossReturn * 100).toFixed(2), costs: (txCost * 100).toFixed(2), net: (netReturn * 100).toFixed(2), sharpe: riskAdjReturn.toFixed(3) };
            }

            if (idx === 3) {
                var S = 100;
                var K = d.param1;
                var vol = d.param2 / 100;
                var r = 0.05;
                var T = 0.25;
                var d1 = (Math.log(S / K) + (r + vol * vol / 2) * T) / (vol * Math.sqrt(T));
                var d2 = d1 - vol * Math.sqrt(T);
                var nd1 = this._normalCDF(d1);
                var nd2 = this._normalCDF(d2);
                var callPrice = S * nd1 - K * Math.exp(-r * T) * nd2;
                var targetK = 100;
                var targetVol = 0.25;
                var td1 = (Math.log(S / targetK) + (r + targetVol * targetVol / 2) * T) / (targetVol * Math.sqrt(T));
                var td2 = td1 - targetVol * Math.sqrt(T);
                var marketPrice = S * this._normalCDF(td1) - targetK * Math.exp(-r * T) * this._normalCDF(td2);
                var priceDiff = Math.abs(callPrice - marketPrice);
                taskScore = Math.min(100, Math.max(0, Math.round(100 - priceDiff * 10)));
                detailKey = 'detail_t4'; detailVals = { model: '$' + callPrice.toFixed(2), market: '$' + marketPrice.toFixed(2), diff: '$' + priceDiff.toFixed(2) };
            }

            if (idx === 4) {
                var alpha = d.param1;
                var beta = d.param2;
                var persistence = alpha + beta;
                var trueAlpha = 0.08;
                var trueBeta = 0.90;
                var alphaErr = Math.abs(alpha - trueAlpha);
                var betaErr = Math.abs(beta - trueBeta);
                var fitQuality = 100 - (alphaErr * 200 + betaErr * 150);
                var longRunVol = Math.sqrt(0.0001 / (1 - persistence));
                taskScore = Math.min(100, Math.max(0, Math.round(fitQuality)));
                detailKey = 'detail_t5'; detailVals = { pers: persistence.toFixed(3), lrv: (longRunVol * 100).toFixed(2), fit: fitQuality.toFixed(1) };
            }

            if (idx === 5) {
                var conf = d.param1 / 100;
                var horizon = d.param2;
                var portfolioVal = 1000000;
                var annualDrift = 0.08;
                var annualVol = 0.22;
                var dailyDrift = annualDrift / 252;
                var dailyVol = annualVol / Math.sqrt(252);
                var zScore = this._inverseNormalCDF(conf);
                var varEstimate = portfolioVal * (dailyDrift * horizon - zScore * dailyVol * Math.sqrt(horizon));
                var targetConf = 0.99;
                var targetHorizon = 10;
                var targetZ = this._inverseNormalCDF(targetConf);
                var regulatoryVaR = portfolioVal * (dailyDrift * targetHorizon - targetZ * dailyVol * Math.sqrt(targetHorizon));
                var regAbs = Math.abs(regulatoryVaR);
                var estAbs = Math.abs(varEstimate);
                var relError = regAbs > 0 ? Math.abs(estAbs - regAbs) / regAbs : 1;
                taskScore = Math.min(100, Math.max(0, Math.round(100 - relError * 100)));
                detailKey = 'detail_t6'; detailVals = { est: '$' + Math.abs(varEstimate).toFixed(0), reg: '$' + Math.abs(regulatoryVaR).toFixed(0), diff: (relError * 100).toFixed(1) };
            }

            detail = this._detailText(detailKey, detailVals);

            state.domainState.totalScore += taskScore;
            state.domainState.completedTasks += 1;
            if (taskScore > state.domainState.bestScore) {
                state.domainState.bestScore = taskScore;
            }
            state.domainState.scoreHistory.push(taskScore);
            state.domainState.taskNames.push(this.ROUNDS[idx].title);

            // --- Persist a normalized 0-100 score for the grading/reporting layer. ---
            // The shared gradebook reads domainState.performance.overallScore; without
            // this it records 0 for every learner. Composite = average task score.
            var overall = Math.min(100, Math.max(0, Math.round(
                state.domainState.totalScore / Math.max(1, state.domainState.completedTasks)
            )));
            var tier = this._tierSlug(overall);
            var grade = this._letter(overall);
            state.domainState.performance = {
                overallScore: overall,
                score: overall,
                grade: grade,
                performanceTier: tier
            };
            state.domainState.performanceTier = tier;

            var results = {
                period: state.currentPeriod,
                taskName: this.ROUNDS[idx].title,
                taskScore: taskScore,
                detail: detail,
                detailKey: detailKey,
                detailVals: detailVals,
                totalScore: state.domainState.totalScore,
                avgScore: Math.round(state.domainState.totalScore / state.domainState.completedTasks),
                overallScore: overall,
                grade: grade,
                performanceTier: tier,
                param1: d.param1,
                param2: d.param2
            };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore',
                (v) => v + ' pts');
            uiManager.bind('gradeDisplay', 'domainState.totalScore',
                (v) => {
                    var avg = v / Math.max(1, window.mySimulation?.state?.domainState?.completedTasks || 1);
                    if (avg >= 85) return 'A';
                    if (avg >= 70) return 'B';
                    if (avg >= 55) return 'C';
                    if (avg >= 40) return 'D';
                    return 'F';
                });
            uiManager.bind('bestScoreDisplay', 'domainState.bestScore',
                (v) => v + ' / 100');
            uiManager.bind('avgScoreDisplay', 'domainState.totalScore',
                (v) => {
                    var tasks = window.mySimulation?.state?.domainState?.completedTasks || 1;
                    return Math.round(v / Math.max(1, tasks)) + ' / 100';
                });
        }

