        getChartData(state) {
            var taskWord = this._t('period_label', 'Task');
            var labels = state.domainState.scoreHistory.map(function(_, i) {
                return taskWord + ' ' + (i + 1);
            });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ label: this._t('chart_task_score', 'Task Score'), data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.taskScore || 0 : 0; });
            var total = scores.reduce(function(s, v) { return s + v; }, 0);
            var avg = Math.round(total / scores.length);
            var best = Math.max.apply(null, scores);
            var worst = Math.min.apply(null, scores);

            var tier = this._tierSlug(avg);

            var insights = [];
            if (avg >= 80) insights.push(this._t('ins_outstanding', 'Outstanding command of computational finance concepts.'));
            else if (avg >= 60) insights.push(this._t('ins_solid', 'Solid grasp of the fundamentals with room for optimization.'));
            else insights.push(this._t('ins_review', 'Review the theoretical foundations and experiment with parameter sensitivity.'));

            if (best - worst > 40) insights.push(this._t('ins_variance', 'Performance varied significantly across tasks. Focus on weaker areas.'));
            if (scores[3] !== undefined && scores[3] >= 80) insights.push(this._t('ins_option', 'Strong understanding of option pricing mechanics.'));
            if (scores[5] !== undefined && scores[5] >= 80) insights.push(this._t('ins_risk', 'Excellent calibration of risk measurement parameters.'));

            return {
                totalScore: total,
                averageScore: avg,
                overallScore: avg,
                bestScore: best,
                worstScore: worst,
                grade: this._letter(avg),
                performance: tier,
                performanceLabel: this._t('tier_' + tier, this._tierLabelEn(tier)),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore
                : (typeof summary.averageScore === 'number') ? summary.averageScore : 0;
            var grade = summary.grade || this._letter(score);
            var tier = summary.performance || this._tierSlug(score);
            var label = summary.performanceLabel || this._t('tier_' + tier, this._tierLabelEn(tier));
            var best = (typeof summary.bestScore === 'number') ? summary.bestScore : 0;
            var avg = (typeof summary.averageScore === 'number') ? summary.averageScore : score;
            var insights = Array.isArray(summary.insights) ? summary.insights : [];

            var of = this._t('cm_of', 'of');
            var html = '' +
                '<div class="codefin-cm">' +
                '<div class="codefin-cm-title">' + this._t('cm_title', 'Lab Complete') + '</div>' +
                '<div class="codefin-cm-score">' + score + '<span class="codefin-cm-score-max"> / 100</span></div>' +
                '<div class="codefin-cm-grade codefin-cm-grade-' + grade + '">' +
                    this._t('cm_grade', 'Grade') + ': <b>' + grade + '</b> &middot; ' + label +
                '</div>' +
                '<div class="codefin-cm-stats">' +
                    '<div class="codefin-cm-stat"><span>' + this._t('cm_best', 'Best Task') + '</span><b>' + best + ' / 100</b></div>' +
                    '<div class="codefin-cm-stat"><span>' + this._t('cm_avg', 'Average') + '</span><b>' + avg + ' / 100</b></div>' +
                '</div>';

            if (insights.length) {
                html += '<div class="codefin-cm-insights"><div class="codefin-cm-insights-h">' +
                    this._t('cm_insights', 'Insights') + '</div><ul>';
                for (var i = 0; i < insights.length; i++) {
                    html += '<li>' + insights[i] + '</li>';
                }
                html += '</ul></div>';
            }
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            var idx = Math.min((state.currentPeriod || 1) - 2, this.ROUNDS.length - 1);
            if (idx < 0) return null;
            if (results.taskScore >= 80) return window.mySimulation.t('hint_excellent');
            if (results.taskScore >= 50) return window.mySimulation.t('hint_good');
            return window.mySimulation.t('hint_poor');
        }

