        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var n = idx + 1;

            // End-of-game: past the last task, hide the input controls so the
            // learner is not presented a stale, re-editable "Task 6" panel.
            var isDone = (state.currentPeriod || 1) > this.ROUNDS.length;
            var submitBtn = document.getElementById('nextPeriodBtn');
            var undoBtn = document.getElementById('undoBtn');
            var inputRow = document.getElementById('codefinInputRow');
            if (isDone) {
                if (submitBtn) submitBtn.style.display = 'none';
                if (undoBtn) undoBtn.style.display = 'none';
                if (inputRow) inputRow.style.display = 'none';
                return;
            }
            if (submitBtn) submitBtn.style.display = '';
            if (undoBtn) undoBtn.style.display = '';
            if (inputRow) inputRow.style.display = '';

            var badge = document.getElementById('taskBadge');
            if (badge) badge.textContent = this._t('period_label', 'Task') + ' ' + n + ' / ' + this.ROUNDS.length;

            var titleEl = document.getElementById('taskTitle');
            if (titleEl) titleEl.innerHTML = this._t('t' + n + '_title', round.title);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._t('t' + n + '_desc', round.description);

            var p1Label = document.getElementById('param1Label');
            if (p1Label) p1Label.textContent = this._t('t' + n + '_p1', round.param1Label);

            var p2Label = document.getElementById('param2Label');
            if (p2Label) p2Label.textContent = this._t('t' + n + '_p2', round.param2Label);

            var p1Hint = document.getElementById('param1Hint');
            if (p1Hint) p1Hint.textContent = this._t('t' + n + '_h1', round.param1Hint);

            var p2Hint = document.getElementById('param2Hint');
            if (p2Hint) p2Hint.textContent = this._t('t' + n + '_h2', round.param2Hint);

            var p1Input = document.getElementById('param1Input');
            if (p1Input) {
                p1Input.min = round.param1Min;
                p1Input.max = round.param1Max;
                p1Input.step = round.param1Step;
                p1Input.value = '';
            }

            var p2Input = document.getElementById('param2Input');
            if (p2Input) {
                p2Input.min = round.param2Min;
                p2Input.max = round.param2Max;
                p2Input.step = round.param2Step;
                p2Input.value = '';
            }
        }

        _letter(score) {
            if (score >= 85) return 'A';
            if (score >= 70) return 'B';
            if (score >= 55) return 'C';
            if (score >= 40) return 'D';
            return 'F';
        }

        _tierSlug(avg) {
            if (avg >= 85) return 'expert';
            if (avg >= 70) return 'proficient';
            if (avg >= 55) return 'intermediate';
            if (avg >= 40) return 'developing';
            return 'novice';
        }

        _tierLabelEn(slug) {
            var m = { novice: 'Novice', developing: 'Developing', intermediate: 'Intermediate', proficient: 'Proficient', expert: 'Expert' };
            return m[slug] || 'Novice';
        }

        _normalCDF(x) {
            var a1 = 0.254829592;
            var a2 = -0.284496736;
            var a3 = 1.421413741;
            var a4 = -1.453152027;
            var a5 = 1.061405429;
            var p = 0.3275911;
            var sign = 1;
            if (x < 0) sign = -1;
            x = Math.abs(x) / Math.sqrt(2);
            var t = 1.0 / (1.0 + p * x);
            var y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
            return 0.5 * (1.0 + sign * y);
        }

        _inverseNormalCDF(p) {
            if (p <= 0) return -Infinity;
            if (p >= 1) return Infinity;
            if (p < 0.5) return -this._inverseNormalCDF(1 - p);
            var t = Math.sqrt(-2 * Math.log(1 - p));
            var c0 = 2.515517;
            var c1 = 0.802853;
            var c2 = 0.010328;
            var d1 = 1.432788;
            var d2 = 0.189269;
            var d3 = 0.001308;
            return t - (c0 + c1 * t + c2 * t * t) / (1 + d1 * t + d2 * t * t + d3 * t * t * t);
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CodeFinAdapter(), {
            simulationType: 'codefin_financial_analysis',
            maxPeriods: 6,
            autoSaveInterval: 30000
        });
    });

